/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['r-base','r-tidyverse','r-data.table']:
  u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?onlyActiveTags=true&limit=20&page=1'
  try:
    with urllib.request.urlopen(u, timeout=30) as fh:d=json.load(fh)
    print(repo, [x['name'] for x in d.get('tags',[])[:6]])
  except Exception as e: print(repo, type(e).__name__)
PY"

